// Umbra PDF offline service worker (iPhone/iPad "Add to Home Screen" and any browser). Generated by
// scripts/build-pwa.mjs, which fills in VERSION and the file lists. Nothing is ever sent anywhere: the app
// only reads its own files, and this keeps a copy of them so it opens and reads text with no connection.
const VERSION = '__VERSION__';
const CACHE = `umbra-${VERSION}`;
const CORE = __CORE__; // needed to open, redact and read English text: cached before the app counts as installed
const MORE = __MORE__; // fetched right after (Chinese OCR, fallback engine, CJK font maps); also cached on first use
const ALL = new Set([...CORE, ...MORE]);

self.addEventListener('install', (e) => {
  e.waitUntil(caches.open(CACHE).then((c) => c.addAll(CORE)));
});

self.addEventListener('activate', (e) => {
  e.waitUntil((async () => {
    for (const k of await caches.keys()) if (k.startsWith('umbra-') && k !== CACHE) await caches.delete(k);
    await self.clients.claim();
    const c = await caches.open(CACHE);
    for (const f of MORE) {
      if (await c.match(f)) continue;
      try { const r = await fetch(f, { cache: 'no-cache' }); if (r.ok) await c.put(f, r); } catch { /* offline: cached on first use */ }
    }
  })());
});

self.addEventListener('message', (e) => { if (e.data === 'skipWaiting') self.skipWaiting(); });

self.addEventListener('fetch', (e) => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== location.origin) return;
  const scope = new URL(self.registration.scope);
  let rel = url.pathname.startsWith(scope.pathname) ? decodeURIComponent(url.pathname.slice(scope.pathname.length)) : null;
  if (rel === null) return;
  if (req.mode === 'navigate' || rel === '') rel = 'index.html';
  if (!ALL.has(rel)) return;
  e.respondWith((async () => {
    const c = await caches.open(CACHE);
    let r = await c.match(rel);
    if (!r) {
      r = await fetch(rel, { cache: 'no-cache' });
      if (r.ok) await c.put(rel, r.clone());
    }
    return r;
  })());
});
